/*==========================================================================*/
#include "dei_system_private.h"
/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
static void dei_system_ign_stat_on	( void );
static void dei_system_ign_stat_off ( void );
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/
static Flg dei_system_flg_ign_stat ;
/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

//--------------------------------------------------------------------------//

void dei_system_ign_stat_init( void )
{
	dei_system_flg_ign_stat = os_flg_create( FALSE );

	//cmd_register:
    {
        static const Cmd_Array1 cmd_array[] = 
        {
            { INPUT_IGN_STATUS_ON , (Exec_Func)dei_system_ign_stat_on  },
	        { INPUT_IGN_STATUS_OFF, (Exec_Func)dei_system_ign_stat_off }
        };

        CMD_LUT_INSERT1(cmd_array,EXEC_MODE_NORMAL);
    }
}

//--------------------------------------------------------------------------//

void dei_system_wait_ign_off( UInt32 timeout_ms )
{
	if( os_flg_state( dei_system_flg_ign_stat ) )
	{
		os_flg_wait_clr(dei_system_flg_ign_stat , timeout_ms ); 
	}
}	

//--------------------------------------------------------------------------//

void dei_system_ign_stat_on( void )
{		
	os_flg_set( dei_system_flg_ign_stat );
}

//--------------------------------------------------------------------------//

void dei_system_ign_stat_off( void )
{
	os_flg_clr( dei_system_flg_ign_stat );
}

//--------------------------------------------------------------------------//

